    '.pf-fred-sheetv span{font-size:13px;color:#c9bfa8;font-weight:400}',
    '.pf-fred-sheetp{font-size:13px;color:#c9bfa8;margin-bottom:8px}',
    '.pf-fred-sheetc{font-size:11px;color:#8a8271;line-height:1.6;margin-bottom:8px}',
