    var qhe = parseInt(el('ptQhEnd').value, 10);
    if (!(qhs >= 0 && qhs <= 23)) { qhs = QH_DEFAULT.start; }
    if (!(qhe >= 0 && qhe <= 23)) { qhe = QH_DEFAULT.end; }
    var b = el('ptSave'), lbl = b ? b.textContent : '';
